class ExportArchiveDownloadView(LoginRequiredMixin, FormView):
    form_class = DownloadArchiveForm
    template_name = 'backups/download.html'

    def form_valid(self, form):
        archive_id = form.cleaned_data['archive_id']
        archive = get_object_or_404(BackupArchive, id=archive_id, account=self.request.user.account)
        return redirect(archive.generate_presigned_download_url())
